int coinChangeMin_5(const vector<int>& coins, int amount) { vector<int> dp(amount + 1, amount + 1); dp[0] = 0; for (int i = 1; i <= amount; ++i) for (int c : coins) if (c <= i) dp[i] = min(dp[i], dp[i - c] + 1); return dp[amount] > amount ? -1 : dp[amount]; }
int coinChangeWays_5(const vector<int>& coins, int amount) { vector<int> dp(amount + 1, 0); dp[0] = 1; for (int c : coins) for (int i = c; i <= amount; ++i) { int cand = dp[i] + dp[i - c]; dp[i] = cand; } return dp[amount]; }
int lcsStrings_5(const string& a, const string& b) { int m = a.size(), n = b.size(); vector<vector<int>> dp(m + 1, vector<int>(n + 1, 0)); for (int i = 1; i <= m; ++i) for (int j = 1; j <= n; ++j) { if (a[i - 1] == b[j - 1]) dp[i][j] = dp[i - 1][j - 1] + 1; else dp[i][j] = dp[i - 1][j] > dp[i][j - 1] ? dp[i - 1][j] : dp[i][j - 1]; } return dp[m][n]; }
int editDistance_5(const string& a, const string& b) { int m = a.size(), n = b.size(); vector<vector<int>> dp(m + 1, vector<int>(n + 1, 0)); for (int i = 0; i <= m; ++i) dp[i][0] = i; for (int j = 0; j <= n; ++j) dp[0][j] = j; for (int i = 1; i <= m; ++i) for (int j = 1; j <= n; ++j) { int best = dp[i - 1][j] < dp[i][j - 1] ? dp[i - 1][j] : dp[i][j - 1]; int diag = dp[i - 1][j - 1]; if (a[i - 1] != b[j - 1]) ++diag; if (diag < best) best = diag; dp[i][j] = best; } return dp[m][n]; }
int minPathSum_5(const vector<vector<int>>& g) { int n = g.size(), m = g[0].size(); vector<vector<int>> dp(n, vector<int>(m, 0)); dp[0][0] = g[0][0]; for (int i = 1; i < n; ++i) dp[i][0] = dp[i - 1][0] + g[i][0]; for (int j = 1; j < m; ++j) dp[0][j] = dp[0][j - 1] + g[0][j]; for (int i = 1; i < n; ++i) for (int j = 1; j < m; ++j) dp[i][j] = (dp[i - 1][j] < dp[i][j - 1] ? dp[i - 1][j] : dp[i][j - 1]) + g[i][j]; return dp[n - 1][m - 1]; }
long long uniquePaths_5(int n, int m) { vector<vector<long long>> dp(n, vector<long long>(m, 1)); for (int i = 1; i < n; ++i) for (int j = 1; j < m; ++j) dp[i][j] = dp[i - 1][j] + dp[i][j - 1]; return dp[n - 1][m - 1]; }
long long fibDP_6(int n) { vector<long long> dp(n + 1, 0); if (n >= 1) dp[1] = 1; for (int i = 2; i <= n; ++i) dp[i] = dp[i - 1] + dp[i - 2]; return dp[n]; }
long long fibTwoVars_6(int n) { if (n <= 1) return n; long long a = 0, b = 1; for (int i = 2; i <= n; ++i) { long long c = a + b; a = b; b = c; } return b; }
long long climbStairs_6(int n) { vector<long long> dp(n + 2, 0); dp[0] = 1; for (int i = 0; i <= n; ++i) { dp[i + 1] += dp[i]; if (i + 2 <= n + 1) dp[i + 2] += dp[i]; } return dp[n]; }
long long houseRobber_6(const vector<int>& a) { long long take = 0, skip = 0; for (int x : a) { long long next = skip + x; if (take > skip) skip = take; take = next; if (take < skip) take = skip; } return take > skip ? take : skip; }
long long kadaneMax_6(const vector<int>& a) { long long best = a[0], cur = a[0]; for (int i = 1; i < (int)a.size(); ++i) { cur += a[i]; if (cur < a[i]) cur = a[i]; if (cur > best) best = cur; } return best; }
